package com.fream.back.global.utils;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Base64;

/**
 * 개인정보 암호화 및 복호화 유틸리티
 * - 양방향 암호화: 상세주소 등 복구가 필요한 데이터
 * - 결정적 암호화: 이름, 전화번호, 주소 등 검색이 필요한 데이터
 */
@Slf4j
@Component
@RequiredArgsConstructor
public class PersonalDataEncryptionUtil {

    @Value("${personal-data.encryption.secret-key}")
    private String secretKey;

    @Value("${personal-data.encryption.iv}")
    private String iv;

    private static final String ALGORITHM = "AES/CBC/PKCS5Padding";
    private static final String DETERMINISTIC_ALGORITHM = "AES/ECB/PKCS5Padding";

    /**
     * 양방향 암호화 (상세주소용)
     * IV를 사용하여 같은 입력이라도 매번 다른 암호화 결과 생성
     *
     * @param plainText 암호화할 원본 문자열
     * @return 암호화된 문자열 (Base64 인코딩)
     */
    public String encrypt(String plainText) {
        if (plainText == null || plainText.isEmpty()) {
            return plainText;
        }

        try {
            Cipher cipher = Cipher.getInstance(ALGORITHM);
            SecretKeySpec keySpec = new SecretKeySpec(secretKey.getBytes(StandardCharsets.UTF_8), "AES");
            IvParameterSpec ivParamSpec = new IvParameterSpec(iv.getBytes(StandardCharsets.UTF_8));

            cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivParamSpec);
            byte[] encrypted = cipher.doFinal(plainText.getBytes(StandardCharsets.UTF_8));

            return Base64.getEncoder().encodeToString(encrypted);
        } catch (Exception e) {
            log.error("데이터 암호화 중 오류 발생: {}", e.getMessage(), e);
            throw new RuntimeException("데이터 암호화 처리 중 오류가 발생했습니다", e);
        }
    }

    /**
     * 양방향 복호화 (상세주소용)
     *
     * @param encryptedText 암호화된 문자열 (Base64 인코딩)
     * @return 복호화된 원본 문자열
     */
    public String decrypt(String encryptedText) {
        if (encryptedText == null || encryptedText.isEmpty()) {
            return encryptedText;
        }

        try {
            Cipher cipher = Cipher.getInstance(ALGORITHM);
            SecretKeySpec keySpec = new SecretKeySpec(secretKey.getBytes(StandardCharsets.UTF_8), "AES");
            IvParameterSpec ivParamSpec = new IvParameterSpec(iv.getBytes(StandardCharsets.UTF_8));

            cipher.init(Cipher.DECRYPT_MODE, keySpec, ivParamSpec);
            byte[] decodedBytes = Base64.getDecoder().decode(encryptedText);
            byte[] decrypted = cipher.doFinal(decodedBytes);

            return new String(decrypted, StandardCharsets.UTF_8);
        } catch (Exception e) {
            log.error("데이터 복호화 중 오류 발생: {}", e.getMessage(), e);
            throw new RuntimeException("데이터 복호화 처리 중 오류가 발생했습니다", e);
        }
    }

    /**
     * 결정적 암호화 (이름, 전화번호, 주소용)
     * 같은 입력에 대해 항상 같은 암호화 결과 생성 -> 검색 가능
     *
     * @param plainText 암호화할 원본 문자열
     * @return 암호화된 문자열 (Base64 인코딩)
     */
    public String deterministicEncrypt(String plainText) {
        if (plainText == null || plainText.isEmpty()) {
            return plainText;
        }

        try {
            // 입력값에 대한 해시를 생성하여 고정된 키 생성
//            String deterministicKey = generateDeterministicKey(plainText);
            byte[] deterministicKeyBytes = generateDeterministicKeyBytes(plainText);

            Cipher cipher = Cipher.getInstance(DETERMINISTIC_ALGORITHM);
//            SecretKeySpec keySpec = new SecretKeySpec(deterministicKey.getBytes(StandardCharsets.UTF_8), "AES");
            SecretKeySpec keySpec = new SecretKeySpec(deterministicKeyBytes, "AES"); // 바이트 배열 직접 사용

            cipher.init(Cipher.ENCRYPT_MODE, keySpec);
            byte[] encrypted = cipher.doFinal(plainText.getBytes(StandardCharsets.UTF_8));

            return Base64.getEncoder().encodeToString(encrypted);
        } catch (Exception e) {
            log.error("결정적 암호화 중 오류 발생: {}", e.getMessage(), e);
            throw new RuntimeException("결정적 암호화 처리 중 오류가 발생했습니다", e);
        }
    }

    private byte[] generateDeterministicKeyBytes(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest((secretKey + input).getBytes(StandardCharsets.UTF_8));

            byte[] keyBytes = new byte[16];
            System.arraycopy(hash, 0, keyBytes, 0, 16);

            return keyBytes; // 문자열 변환 없이 바이트 배열 그대로 반환
        } catch (Exception e) {
            log.error("결정적 키 생성 중 오류 발생: {}", e.getMessage(), e);
            throw new RuntimeException("결정적 키 생성 중 오류가 발생했습니다", e);
        }
    }



    /**
     * 결정적 복호화 (이름, 전화번호, 주소용)
     *
     * @param encryptedText 암호화된 문자열
     * @return 복호화된 원본 문자열
     */
    public String deterministicDecrypt(String encryptedText) {
        if (encryptedText == null || encryptedText.isEmpty()) {
            return encryptedText;
        }

        try {
            // 복호화를 위해 모든 가능한 키를 시도해야 하므로
            // 실제로는 원본 값과 비교하는 방식으로 사용
            // 또는 별도의 매핑 테이블 필요

            // 임시로 기본키로 복호화 시도
            Cipher cipher = Cipher.getInstance(DETERMINISTIC_ALGORITHM);
            SecretKeySpec keySpec = new SecretKeySpec(secretKey.getBytes(StandardCharsets.UTF_8), "AES");

            cipher.init(Cipher.DECRYPT_MODE, keySpec);
            byte[] decodedBytes = Base64.getDecoder().decode(encryptedText);
            byte[] decrypted = cipher.doFinal(decodedBytes);

            return new String(decrypted, StandardCharsets.UTF_8);
        } catch (Exception e) {
            log.error("결정적 복호화 중 오류 발생: {}", e.getMessage(), e);
            throw new RuntimeException("결정적 복호화 처리 중 오류가 발생했습니다", e);
        }
    }

    /**
     * 입력값 기반 결정적 키 생성
     */
//    private String generateDeterministicKey(String input) {
//        try {
//            MessageDigest digest = MessageDigest.getInstance("SHA-256");
//            byte[] hash = digest.digest((secretKey + input).getBytes(StandardCharsets.UTF_8));
//
//            // 32바이트 중 처음 16바이트만 사용 (AES-128)
//            byte[] keyBytes = new byte[16];
//            System.arraycopy(hash, 0, keyBytes, 0, 16);
//
//            return new String(keyBytes, StandardCharsets.UTF_8);
//        } catch (Exception e) {
//            log.error("결정적 키 생성 중 오류 발생: {}", e.getMessage(), e);
//            throw new RuntimeException("결정적 키 생성 중 오류가 발생했습니다", e);
//        }
//    }

    /**
     * 검색용 암호화된 값 생성
     * 검색 시 사용할 암호화된 값을 생성
     *
     * @param plainText 검색할 원본 문자열
     * @return 검색용 암호화된 문자열
     */
    public String encryptForSearch(String plainText) {
        return deterministicEncrypt(plainText);
    }

    /**
     * 암호화된 데이터인지 확인 (Base64 형식인지 검사)
     *
     * @param text 검사할 문자열
     * @return 암호화된 데이터 여부
     */
    public boolean isEncrypted(String text) {
        if (text == null || text.isEmpty()) {
            return false;
        }

        try {
            // Base64 디코딩 시도
            Base64.getDecoder().decode(text);
            return true;
        } catch (IllegalArgumentException e) {
            return false;
        }
    }
}package com.fream.back.domain.address.service.query;

import com.fream.back.domain.address.dto.AddressResponseDto;
import com.fream.back.domain.address.entity.Address;
import com.fream.back.domain.address.exception.AddressErrorCode;
import com.fream.back.domain.address.exception.AddressException;
import com.fream.back.domain.address.exception.AddressNotFoundException;
import com.fream.back.domain.address.exception.AddressUserNotFoundException;
import com.fream.back.domain.address.repository.AddressRepository;
import com.fream.back.domain.user.entity.User;
import com.fream.back.domain.user.repository.UserRepository;
import com.fream.back.global.utils.PersonalDataEncryptionUtil;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
@Slf4j
public class AddressQueryService {

    private final UserRepository userRepository;
    private final AddressRepository addressRepository;
    private final PersonalDataEncryptionUtil encryptionUtil;

    //주소지 목록 조회
    @Transactional(readOnly = true)
    public List<AddressResponseDto> getAddresses(String email) {
        try {
            log.info("주소 목록 조회 시작: 사용자={}", email);

            // 이메일을 암호화해서 사용자 조회
            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
            User user = userRepository.findByEmail(encryptedEmail)
                    .orElseThrow(() -> new AddressUserNotFoundException(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            List<AddressResponseDto> addresses = user.getAddresses().stream()
                    .map(address -> new AddressResponseDto(
                            address.getId(),
                            // 결정적 암호화된 필드들 복호화
                            encryptionUtil.deterministicDecrypt(address.getRecipientName()),
                            encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
                            encryptionUtil.deterministicDecrypt(address.getZipCode()),
                            encryptionUtil.deterministicDecrypt(address.getAddress()),
                            // 상세주소는 양방향 암호화 복호화
                            address.getDetailedAddress() != null ?
                                    encryptionUtil.decrypt(address.getDetailedAddress()) : null,
                            address.isDefault()))
                    .collect(Collectors.toList());

            log.info("주소 목록 조회 완료: 사용자={}, 조회된 주소 수={}", email, addresses.size());
            return addresses;
        } catch (AddressException e) {
            throw e; // 이미 AddressException이면 그대로 전파
        } catch (Exception e) {
            log.error("주소 목록 조회 중 오류 발생: 사용자={}, 오류={}", email, e.getMessage(), e);
            throw new AddressException(AddressErrorCode.ADDRESS_QUERY_ERROR, e);
        }
    }

    //단일 주소지 조회
    @Transactional(readOnly = true)
    public AddressResponseDto getAddress(String email, Long addressId) {
        try {
            log.info("단일 주소 조회 시작: 사용자={}, 주소ID={}", email, addressId);

            // 이메일을 암호화해서 사용자 조회
            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
            User user = userRepository.findByEmail(encryptedEmail)
                    .orElseThrow(() -> new AddressUserNotFoundException(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            Address address = addressRepository.findByIdAndUser(addressId, user)
                    .orElseThrow(() -> new AddressNotFoundException(
                            "주소 ID '" + addressId + "'에 해당하는 주소를 찾을 수 없습니다."
                    ));

            // 암호화 방식에 따라 적절한 복호화 적용
            AddressResponseDto responseDto = new AddressResponseDto(
                    address.getId(),
                    // 결정적 암호화된 필드들 복호화
                    encryptionUtil.deterministicDecrypt(address.getRecipientName()),
                    encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
                    encryptionUtil.deterministicDecrypt(address.getZipCode()),
                    encryptionUtil.deterministicDecrypt(address.getAddress()),
                    // 상세주소는 양방향 암호화 복호화
                    address.getDetailedAddress() != null ?
                            encryptionUtil.decrypt(address.getDetailedAddress()) : null,
                    address.isDefault()
            );

            log.info("단일 주소 조회 완료: 사용자={}, 주소ID={}", email, addressId);
            return responseDto;
        } catch (AddressException e) {
            throw e; // 이미 AddressException이면 그대로 전파
        } catch (Exception e) {
            log.error("단일 주소 조회 중 오류 발생: 사용자={}, 주소ID={}, 오류={}",
                    email, addressId, e.getMessage(), e);
            throw new AddressException(AddressErrorCode.ADDRESS_QUERY_ERROR, e);
        }
    }

    /**
     * 수신자 이름으로 주소 검색 (결정적 암호화 활용)
     */
    @Transactional(readOnly = true)
    public List<AddressResponseDto> searchAddressesByRecipientName(String email, String recipientName) {
        try {
            log.info("이름으로 주소 검색 시작: 사용자={}, 검색어={}", email, recipientName);

            // 이메일을 암호화해서 사용자 조회
            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
            User user = userRepository.findByEmail(encryptedEmail)
                    .orElseThrow(() -> new AddressUserNotFoundException(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            // 검색어를 암호화하여 DB와 비교
            String encryptedSearchTerm = encryptionUtil.encryptForSearch(recipientName);

            // Repository에서 암호화된 이름으로 검색하는 메서드 필요
            List<Address> foundAddresses = addressRepository.findByUserAndRecipientName(user, encryptedSearchTerm);

            List<AddressResponseDto> addresses = foundAddresses.stream()
                    .map(address -> new AddressResponseDto(
                            address.getId(),
                            encryptionUtil.deterministicDecrypt(address.getRecipientName()),
                            encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
                            encryptionUtil.deterministicDecrypt(address.getZipCode()),
                            encryptionUtil.deterministicDecrypt(address.getAddress()),
                            address.getDetailedAddress() != null ?
                                    encryptionUtil.decrypt(address.getDetailedAddress()) : null,
                            address.isDefault()))
                    .collect(Collectors.toList());

            log.info("이름으로 주소 검색 완료: 사용자={}, 검색어={}, 결과 수={}",
                    email, recipientName, addresses.size());
            return addresses;
        } catch (AddressException e) {
            throw e;
        } catch (Exception e) {
            log.error("이름으로 주소 검색 중 오류 발생: 사용자={}, 검색어={}, 오류={}",
                    email, recipientName, e.getMessage(), e);
            throw new AddressException(AddressErrorCode.ADDRESS_QUERY_ERROR, e);
        }
    }

    /**
     * 전화번호로 주소 검색 (결정적 암호화 활용)
     */
    @Transactional(readOnly = true)
    public List<AddressResponseDto> searchAddressesByPhoneNumber(String email, String phoneNumber) {
        try {
            log.info("전화번호로 주소 검색 시작: 사용자={}, 검색어={}", email, phoneNumber);

            // 이메일을 암호화해서 사용자 조회
            String encryptedEmail = encryptionUtil.deterministicEncrypt(email);
            User user = userRepository.findByEmail(encryptedEmail)
                    .orElseThrow(() -> new AddressUserNotFoundException(
                            "이메일 '" + email + "'에 해당하는 사용자를 찾을 수 없습니다."
                    ));

            // 검색어를 암호화하여 DB와 비교
            String encryptedSearchTerm = encryptionUtil.encryptForSearch(phoneNumber);

            // Repository에서 암호화된 전화번호로 검색하는 메서드 필요
            List<Address> foundAddresses = addressRepository.findByUserAndPhoneNumber(user, encryptedSearchTerm);

            List<AddressResponseDto> addresses = foundAddresses.stream()
                    .map(address -> new AddressResponseDto(
                            address.getId(),
                            encryptionUtil.deterministicDecrypt(address.getRecipientName()),
                            encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
                            encryptionUtil.deterministicDecrypt(address.getZipCode()),
                            encryptionUtil.deterministicDecrypt(address.getAddress()),
                            address.getDetailedAddress() != null ?
                                    encryptionUtil.decrypt(address.getDetailedAddress()) : null,
                            address.isDefault()))
                    .collect(Collectors.toList());

            log.info("전화번호로 주소 검색 완료: 사용자={}, 검색어={}, 결과 수={}",
                    email, phoneNumber, addresses.size());
            return addresses;
        } catch (AddressException e) {
            throw e;
        } catch (Exception e) {
            log.error("전화번호로 주소 검색 중 오류 발생: 사용자={}, 검색어={}, 오류={}",
                    email, phoneNumber, e.getMessage(), e);
            throw new AddressException(AddressErrorCode.ADDRESS_QUERY_ERROR, e);
        }
    }
